"""Regular-language objects for the offline predicate language.

The toolkit grammar is deliberately small: a union of sequences, a sequence of
atoms, postfix ``*`` repetition, parenthesised groups and character classes.
Escapes work inside and outside classes.  Matching is a full match over
Latin-1 code points; ranges never match bytes they exclude.
"""

from typing import List, Tuple


class Regex(object):
    """Base class of every regular-language expression."""

    def ranges(self):
        return ()

    def __str__(self):
        return ''


class Empty(Regex):
    """Matches only the empty string."""

    def __str__(self):
        return ''


class Range(Regex):
    """Matches one code point inside an inclusive range."""

    def __init__(self, low, high):
        if len(low) != 1 or len(high) != 1:
            raise ValueError('Range must be single characters')
        self.low = low
        self.high = high

    def ranges(self):
        return ((self.low, self.high),)

    def __str__(self):
        return '[%s-%s]' % (self.low, self.high)


class Chars(Regex):
    """Matches one code point from a set of ranges."""

    def __init__(self, ranges):
        self._ranges = tuple(ranges)

    def ranges(self):
        return self._ranges

    def __str__(self):
        return '[%s]' % ''.join('%s-%s' % item for item in self._ranges)


class Choice(Regex):
    """Matches any of the alternatives."""

    def __init__(self, *args):
        if len(args) < 2:
            raise ValueError('Choice needs at least two expressions')
        self.exprs = list(args)

    def __str__(self):
        return '(%s)' % '|'.join(str(item) for item in self.exprs)


class Seq(Regex):
    """Matches the concatenation of every expression."""

    def __init__(self, *args):
        if len(args) < 2:
            raise ValueError('Seq needs at least two expressions')
        self.exprs = list(args)

    def __str__(self):
        return '(%s)' % ''.join(str(item) for item in self.exprs)


class Star(Regex):
    """Matches zero or more repetitions."""

    def __init__(self, expr):
        self.expr = expr

    def __str__(self):
        return '(%s)*' % str(self.expr)


def chars(low, high):
    """A range expression."""
    return Range(low, high)


def text(value):
    """An expression matching exactly the given text."""
    if value == '':
        return empty()
    if len(value) == 1:
        return chars(value, value)
    return seq(*[chars(item, item) for item in value])


def choice(*args):
    """A union expression."""
    return Choice(*args)


def seq(*args):
    """A concatenation expression."""
    return Seq(*args)


def star(expr):
    """A repetition expression."""
    return Star(expr)


def plus(expr):
    """One or more repetitions."""
    return seq(expr, star(expr))


def empty():
    """The empty string."""
    return Empty()


class _Node(object):
    """Internal parser node."""

    __slots__ = ('kind', 'children', 'items')

    def __init__(self, kind, children=(), items=()):
        self.kind = kind
        self.children = list(children)
        self.items = list(items)


class _State(object):
    """One NFA state."""

    __slots__ = ('eps', 'moves')

    def __init__(self):
        self.eps = []
        self.moves = []


class Program(object):
    """A compiled regular language."""

    __slots__ = ('states', 'start', 'accept')

    def __init__(self, states, start, accept):
        self.states = states
        self.start = start
        self.accept = accept


def _parse_alt(pattern, index):
    branches = []
    while True:
        node, index = _parse_seq(pattern, index)
        branches.append(node)
        if index < len(pattern) and pattern[index] == '|':
            index += 1
            continue
        break
    if len(branches) == 1:
        return branches[0], index
    return _Node('alt', branches), index


def _parse_seq(pattern, index):
    items = []
    while index < len(pattern) and pattern[index] not in '|)':
        node, index = _parse_repeat(pattern, index)
        items.append(node)
    if not items:
        return _Node('empty'), index
    if len(items) == 1:
        return items[0], index
    return _Node('seq', items), index


def _parse_repeat(pattern, index):
    node, index = _parse_atom(pattern, index)
    while index < len(pattern) and pattern[index] == '*':
        index += 1
        node = _Node('star', [node])
    return node, index


def _parse_atom(pattern, index):
    char = pattern[index]
    if char == '(':
        node, index = _parse_alt(pattern, index + 1)
        if index >= len(pattern) or pattern[index] != ')':
            raise ValueError('unbalanced parenthesis')
        return node, index + 1
    if char == '[':
        return _parse_class(pattern, index)
    if char == '\\':
        if index + 1 >= len(pattern):
            raise ValueError('dangling escape')
        return _Node('chars', (), ((pattern[index + 1], pattern[index + 1]),)), index + 2
    return _Node('chars', (), ((char, char),)), index + 1


def _read_class_char(pattern, index):
    if pattern[index] == '\\':
        if index + 1 >= len(pattern):
            raise ValueError('dangling escape')
        return pattern[index + 1], index + 2
    return pattern[index], index + 1


def _parse_class(pattern, index):
    index += 1
    items = []
    while index < len(pattern) and pattern[index] != ']':
        low, index = _read_class_char(pattern, index)
        if (index < len(pattern) and pattern[index] == '-'
                and index + 1 < len(pattern) and pattern[index + 1] != ']'):
            index += 1
            high, index = _read_class_char(pattern, index)
            items.append((low, high))
        else:
            items.append((low, low))
    if index >= len(pattern):
        raise ValueError('unterminated class')
    return _Node('chars', (), tuple(items)), index + 1


def _compile(node, states):
    kind = node.kind
    if kind == 'empty':
        start = _State()
        accept = _State()
        states.append(start)
        states.append(accept)
        start.eps.append(len(states) - 1)
        return len(states) - 2, len(states) - 1
    if kind == 'chars':
        start = _State()
        accept = _State()
        states.append(start)
        states.append(accept)
        start.moves.append((node.items, len(states) - 1))
        return len(states) - 2, len(states) - 1
    if kind == 'seq':
        first, previous = _compile(node.children[0], states)
        for child in node.children[1:]:
            start, accept = _compile(child, states)
            states[previous].eps.append(start)
            previous = accept
        return first, previous
    if kind == 'alt':
        start = _State()
        states.append(start)
        accept = _State()
        states.append(accept)
        for child in node.children:
            child_start, child_accept = _compile(child, states)
            states[start].eps.append(child_start)
            states[child_accept].eps.append(len(states) - 1)
        return len(states) - 2, len(states) - 1
    if kind == 'star':
        start = _State()
        states.append(start)
        accept = _State()
        states.append(accept)
        child_start, child_accept = _compile(node.children[0], states)
        states[start].eps.append(child_start)
        states[start].eps.append(len(states) - 1)
        states[child_accept].eps.append(len(states) - 1)
        return len(states) - 2, len(states) - 1
    raise ValueError('unknown node')


def compile_pattern(pattern):
    """Compile a toolkit pattern into a matching program."""
    node, index = _parse_alt(pattern, 0)
    if index != len(pattern):
        raise ValueError('trailing pattern data')
    states = []
    start, accept = _compile(node, states)
    return Program(states, start, accept)


def _closure(states, group):
    seen = set()
    stack = list(group)
    out = set()
    while stack:
        current = stack.pop()
        if current in seen:
            continue
        seen.add(current)
        out.add(current)
        stack.extend(states[current].eps)
    return out


def _matches(items, char):
    for low, high in items:
        if low <= char <= high:
            return True
    return False


def fullmatch(program, text):
    """True when the whole text belongs to the compiled language."""
    states = program.states
    current = _closure(states, [program.start])
    for char in text:
        following = []
        for index in current:
            for items, target in states[index].moves:
                if _matches(items, char):
                    following.append(target)
        if not following:
            return False
        current = _closure(states, following)
    return program.accept in current


def ismatch(regex, text):
    """Determine if a string matches a regular expression."""
    if isinstance(regex, Program):
        return fullmatch(regex, text)
    return fullmatch(compile_pattern(str(regex)), text)
